        "VPA": {
            "Payer": "select result->''score''->>''decisiondetails'' as \\"decisiondetails\\", ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcuniquetransid as \\"UniqueID-DL\\", vcclassname as \\"Class\\",  dttrxntime  as \\"Time\\", cast(dttrxntime at time zone :timeZone as date) as \\"Date\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' when result->>''status''=''Success'' then ''true'' when result->>''status'' IS NULL then CASE WHEN score > 0 THEN ''false'' WHEN score = 0  THEN ''true'' else NULL end   end   \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", vcpayeraccountexternalid as \\"Payer Account-DL\\", vcpayeraddr as \\"PayerVPA-DL\\", vcpayeeaccountexternalid as \\"Payee Account-DL\\", vcpayeeaddr as \\"PayeeVPA-DL\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as  \\"PayeeName\\", cast ( observations->''txn''->''type''->>-1 as text) as \\"Txn Type\\", ipayeemccid as \\"Payee MCC\\",cast(observations-> ''txn''->''attribs''->''skip_processing'' as int) as \\"Skip Processing\\" from analytics.trans where vcclassname in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser AND iorgid =:orgid  and mappingtype = ''TransactionClass'') (select vcclassname FROM ui.transactionclasses where (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid)) and itenantid = :tenantid and vcpayeraddr = :useraddress and dttrxntime between (cast(cast(:date as date)-1 as timestamp) at time zone :timeZone ) and (cast(:date as date)+ 1 - interval ''1 sec'') at time zone :timeZone  order by dttrxntime desc limit 50000;",
